CREATE OR REPLACE FUNCTION public.pipeline_add_artifact(_id uuid,_kind text,_path text,_name text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v uuid; BEGIN PERFORM public.pipeline_assert_admin(); IF lower(_kind)='w9' THEN RAISE EXCEPTION 'Taxpayer information is collected securely by Stripe. W-9 uploads are not accepted.'; END IF; INSERT INTO public.contractor_artifacts(applicant_id,kind,storage_path,file_name,uploaded_by) VALUES(_id,_kind,_path,_name,auth.uid()) RETURNING id INTO v; RETURN v; END $$;